"""Guard the dependency boundaries used by the project skeleton."""

import ast
import sys
import unittest
from pathlib import Path

APP = Path(__file__).resolve().parents[1] / "app"


class ArchitectureTests(unittest.TestCase):
    def test_domain_models_only_import_standard_library_and_domain_modules(self):
        for path in (APP / "models").glob("*.py"):
            tree = ast.parse(path.read_text())
            for node in ast.walk(tree):
                if isinstance(node, ast.ImportFrom) and node.level:
                    self.assertEqual(node.level, 1, str(path))
                elif isinstance(node, (ast.Import, ast.ImportFrom)):
                    modules = (
                        [alias.name for alias in node.names]
                        if isinstance(node, ast.Import)
                        else [node.module or ""]
                    )
                    for module in modules:
                        self.assertIn(
                            module.split(".")[0], sys.stdlib_module_names, str(path)
                        )

    def test_online_modules_do_not_load_build_parsers(self):
        for path in APP.rglob("*.py"):
            if "knowledge_build" in path.parts:
                continue
            tree = ast.parse(path.read_text())
            for node in ast.walk(tree):
                if isinstance(node, ast.ImportFrom):
                    self.assertNotIn("knowledge_build", node.module or "", str(path))
                    self.assertNotIn(
                        "knowledge_build",
                        [alias.name for alias in node.names],
                        str(path),
                    )
                elif isinstance(node, ast.Import):
                    self.assertFalse(
                        any("knowledge_build" in alias.name for alias in node.names),
                        str(path),
                    )

    def test_environment_reads_stay_in_config(self):
        for path in APP.rglob("*.py"):
            if "config" in path.parts:
                continue
            source = path.read_text()
            self.assertNotIn("os.environ", source, str(path))
            self.assertNotIn("os.getenv", source, str(path))
